    // dégât restait borné (aucune application automatique, l'item finit en
    // chip), mais un contrôle qu'on annonce et qui ne s'exécute pas est
    // pire qu'un contrôle absent. Sans `skill`, le scope est indéfinissable
    // — donc rien à autoriser.
    const violation = r.skill
      ? scopeLintViolation(r.skill, r.changedPaths ?? [])
      : 'skill absent — scope indéfinissable, aucun chemin ne peut être autorisé';
    if (violation) {
      outcomes.push(`${itemKey} : REJETÉ — diff hors scope (${violation})`);
      // Le rejet est SCELLÉ par un marqueur (il ne sera jamais rejoué) :
      // il doit donc remonter dans `gaps` — donc au hub — au même titre
      // qu'un side-effect en échec juste en dessous. Sans ça, un diff
      // d'amélioration refusé n'existait que dans le stdout d'UNE
      // invocation de CLI, et disparaissait avec elle.
      gaps.push(`${itemKey} : diff d'amélioration REJETÉ par le scope-lint (${violation}) — scellé, jamais rejoué`);
      if (!opts.dryRun) await writeMarker(markerP, resultsBranch.sha, itemKey, 'rejected-scope-lint');
      continue;
