}

/**
 * Pousse un message d'abandon dans `gaps` UNE SEULE FOIS — au moment précis
 * où `newAttempts` (le compteur juste après incrément par
 * `recordJudgeLocalFailure`) atteint EXACTEMENT `maxAttempts` — fix (revue
 * adversariale round 2 — "un candidat abandonné ré-ouvre une conversation
 * d'écart CHAQUE nuit, indéfiniment") : `abandoned` (voir
 * `computeJudgeLocalSelection`) est recalculé À CHAQUE invocation depuis
 * l'état persisté — un candidat déjà au-delà de `maxAttempts` AVANT cette
 * invocation y réapparaîtrait donc éternellement si on le repoussait vers
 * `gaps` telle quelle chaque nuit, rouvrant une conversation "note" fraîche
 * (id déterministe par DATE) sans jamais s'arrêter.
 *
 * Décision (parmi les deux options du finding) : signaler au moment du
 * franchissement plutôt que via un drapeau persistant — un drapeau
 * exigerait un nouveau champ sur `SkillJob`/`SessionReviewStamp`
 * (`src/types/review.ts`), hors du périmètre de cette correction (limitée à
 * `evalsReconciler.ts`/son test, voir le dispatch). Un candidat DÉJÀ
 * abandonné avant cette invocation ne repasse JAMAIS par
 * `recordJudgeLocalFailure` ici (il est exclu de `selected`/`eligible`, et le
 * traitement des sessions irrésolubles saute aussi tout candidat déjà
 * au-delà de `maxAttempts` — voir `cmdJudgeLocal`) : il a donc déjà été
 * signalé la nuit où il a franchi le seuil, jamais re-signalé les nuits
 * suivantes.
 *
 * Fix P2 (revue adversariale round 3, l.2398 — "l'échec du compteur qui
 * borne la dépense n'est signalé qu'au log launchd") : quand
 * `recordJudgeLocalFailure` retourne `undefined` (conflit d'écriture non
 * résolu après ses reprises, ou enregistrement disparu), `maxAttempts` cesse
 * SILENCIEUSEMENT de border la dépense pour CE candidat précis — son
 * compteur persisté n'a pas bougé, il sera donc re-sélectionné (et RE-PAYÉ,
 * jugement complet) la prochaine invocation. C'est EXACTEMENT le cas où la
 * dépense devient illimitée, et jusqu'ici le SEUL chemin terminal de ce
 * fichier qui ne remontait qu'à `outcomes` (stdout d'un launchd que personne
 * ne lit, voir les commentaires plus haut sur ce même sujet) sans jamais
 * toucher `gaps`/le hub. Chaque appelant de `recordJudgeLocalFailure` appelle
 * déjà cette fonction juste après (voir tous les sites d'appel) — router ce
 * cas ICI, une seule fois, couvre donc TOUS les chemins terminaux d'un coup,
 * plutôt que de dupliquer la même vérification à chaque site d'appel.
 */
function noteAbandonmentIfJustCrossed(
  gaps: string[],
  id: string,
  kind: string,
  skill: string,
  newAttempts: number | undefined,
  maxAttempts: number,
  lastError?: string,
): void {
  if (newAttempts === undefined) {
    gaps.push(
      `${id} (${kind}, skill ${skill}) : échec du jugement local ENREGISTRÉ mais compteur localJudgeAttempts NON incrémenté ` +
        `(conflit d'écriture persistant, ou enregistrement disparu) — maxAttempts=${maxAttempts} ne borne plus ce candidat, ` +
        'risque de re-dépense illimitée tant que ce conflit persiste',
    );
    return;
  }
  if (newAttempts === maxAttempts) {
    gaps.push(
      `${id} (${kind}, skill ${skill}) : abandonné après ${newAttempts} échec(s) local (>= maxAttempts=${maxAttempts})` +
        // Sans la cause, l'écart ne dit pas quoi faire (vécu 2026-10-01 : un transcript de 149 Mo > cap de 50 Mo,
        // déterministe, retenté 3 nuits de suite — la raison n'était que dans ~/Library/Logs/evals-judge-local.log).
        (lastError ? ` — dernière cause : ${lastError.length > 300 ? `${lastError.slice(0, 300)}…` : lastError}` : '') +
        ' — ne sera plus jamais retenté automatiquement (signalé une seule fois, à l’instant où le seuil est franchi)',
    );
  }
}

/**
 * Réarmement manuel d'un candidat abandonné — voir la docstring de
 * `resetAttempts` sur `cmdJudgeLocal` pour la justification du choix
 * (sous-commande explicite plutôt que classification automatique
 * infra/verdict). Remet `localJudgeAttempts` à 0 et efface
 * `localJudgeLastError`, pour un SkillJob OU une session (essaie les deux
 * stores, un `candidateId` étant soit un jobId soit un sessionId, jamais les
 * deux). Prend le MÊME verrou partagé que le reste de ce fichier — cette
 * écriture touche le même enregistrement qu'un run réel de `judge-local`
 * pourrait être en train de lire/modifier.
 *
 * N'exige PAS que le candidat soit actuellement `abandonné` (>= maxAttempts)
 * — un remise à zéro reste inoffensive même appliquée tôt (jamais un moyen
 * de contourner `maxAttempts` PENDANT une même nuit : les marqueurs du jour,
 * scopés par date, continuent de protéger contre un double jugement le même
 * jour, voir `markersToday.markedIds`).
 */
async function cmdJudgeLocalResetAttempts(candidateId: string): Promise<void> {
  // Fix B2 (audit fiabilité rail, 2026-08-12) : `--reset-attempts` est un
  // geste EXPLICITE d'un humain qui vient de lire `localJudgeLastError` (voir
  // la docstring de `resetAttempts` sur `cmdJudgeLocal`) — jamais une opération
  // planifiée par un LaunchAgent. Le réessai de 4 min existe pour absorber
  // une collision de RÉVEIL entre jobs nocturnes espacés, pas pour faire
  // attendre quelqu'un devant son terminal : `{ attempts: 1 }` supprime le
  // réessai (aucune alerte possible de toute façon, `label !== 'export'`).
  const lock = await acquireLock('judge-local-reset-attempts', { attempts: 1 });
  if (!lock.acquired) {
    printNoop(lock.reason ?? 'verrou indisponible', lock.held);
    return;
  }
  try {
    const job = await getSkillJob(candidateId);
    if (job) {
      await updateSkillJob(candidateId, { localJudgeAttempts: 0, localJudgeLastError: undefined }, job.updatedAt);
      process.stdout.write(
        `VERDICT: JUDGE_LOCAL_RESET\n${candidateId} (skillJob) : localJudgeAttempts remis à 0, localJudgeLastError effacé.\n`,
      );
      return;
    }
    const stamp = await getSessionStamp(candidateId);
    if (stamp) {
      await updateSessionStamp(candidateId, { localJudgeAttempts: 0, localJudgeLastError: undefined }, stamp.updatedAt);
      process.stdout.write(
        `VERDICT: JUDGE_LOCAL_RESET\n${candidateId} (session) : localJudgeAttempts remis à 0, localJudgeLastError effacé.\n`,
      );
      return;
    }
    process.stdout.write(
      `VERDICT: JUDGE_LOCAL_RESET_NOT_FOUND\nAucun SkillJob ni SessionReviewStamp pour l'id "${candidateId}".\n`,
    );
  } finally {
    await releaseLock();
  }
}

export async function cmdJudgeLocal(opts: {
  dryRun: boolean;
  force: boolean;
  /**
   * Réarmement manuel (fix P3, revue adversariale round 3 — "trois échecs
   * TRANSITOIRES retirent définitivement un candidat, sans chemin de
   * réarmement") : `--force` outrepasse explicitement le SEUL interrupteur
   * `enabled` (voir plus bas), jamais `maxAttempts` — un candidat abandonné
   * après un échec purement transitoire (disque plein, permissions, conflit
   * d'écriture passager — voir les branches non-fail-closed de la boucle de
   * sélection ci-dessous) n'avait donc AUCUN moyen de repartir, même une fois
   * la cause corrigée.
   *
   * Décision (parmi les deux options du finding) : une SOUS-COMMANDE
   * explicite (`--reset-attempts <candidateId>`) plutôt que de distinguer
   * automatiquement "échec d'infrastructure" vs "échec de verdict" — les six
   * chemins d'échec de ce fichier (transcript introuvable, marqueur
   * `verdict-obtained` corrompu, rejeu d'application, exception non
   * fail-closed pendant `runLocalJudge`, verdict jugé inexploitable,
   * application post-verdict en échec) ne se laissent PAS classer de façon
   * fiable en "transitoire" vs "définitif" sans risquer de mal classer un
   * échec réellement systémique comme transitoire — ce qui romprait
   * SILENCIEUSEMENT la garantie centrale de ce fichier ("maxAttempts borne
   * TOUJOURS la dépense"). Un réarmement EXPLICITE, déclenché par un humain
   * qui a lu `localJudgeLastError` et décidé que la cause est bien réglée,
   * ne prend jamais cette décision à la place de Franck — même philosophie
   * que `--force` pour `enabled` : jamais silencieux, toujours un geste
   * délibéré et auditable.
   */
  resetAttempts?: string;
}): Promise<void> {
  // Traité AVANT tout — indépendant de `enabled`/`--dry-run` (une opération
  // de maintenance ponctuelle, pas un run de jugement) : voir la docstring du
  // paramètre ci-dessus.
  if (opts.resetAttempts) {
    await cmdJudgeLocalResetAttempts(opts.resetAttempts);
    return;
  }

  const cfg = await loadEvalsConfig();

  // Borne n°1 (interrupteur) — ne s'applique QU'AU RUN RÉEL, vérifiée AVANT
  // le verrou (`enabled: false` ne doit rien faire du tout, pas même
  // créer/retirer le fichier de verrou). Un `--dry-run` ne spawn JAMAIS
  // `claude -p` et n'écrit jamais rien par construction (voir plus bas) :
  // c'est explicitement "le mode que Franck lancera pour regarder sans
  // risque" (§ Lot 3, DONE du lot) — il doit rester consultable À TOUT
  // MOMENT, MÊME l'interrupteur coupé, sans jamais avoir besoin de --force.
  // `--force` outrepasse donc CETTE SEULE borne, et UNIQUEMENT pour un run
  // RÉEL (c'est ce que le Lot 5 utilisera) — jamais maxPerNight, jamais
  // maxAttempts, jamais requis ni utile en --dry-run.
  if (!opts.dryRun && !cfg.localJudge.enabled && !opts.force) {
    process.stdout.write(
      [
        'VERDICT: NOOP',
        "Raison : localJudge.enabled=false (config/evals.json) — juge local désactivé. --force outrepasse CE SEUL interrupteur, pas les autres bornes.",

      outcomes.push(
        `${stale.candidateId} : marqueur 'judging' périmé du ${stale.fileDate} — neutralisation en échec d'écriture, non finalisée (${orphanTimeoutMarkerResult.error})`,
      );
    }
    continue;
  }
  // Sous-contrat 3bis (D2) : marqueur D'ABORD (avec reprise bornée, voir
  // `writeJudgeLocalMarkerGuarded`/`'terminal-recordable'`), PUIS
  // `recordJudgeLocalFailure` UNIQUEMENT si le marqueur a été finalisé
  // avec succès — anti-double-comptage. AVANT ce fix, l'ordre était
  // INVERSÉ ici (`recordJudgeLocalFailure` puis l'écriture, seule non
  // protégée) : un échec d'écriture APRÈS un incrément déjà posé aurait
  // laissé le marqueur bloqué à 'judging' alors que le compteur d'échec
  // avait déjà avancé — un futur rattrapage `findStaleJudgingMarkers` le
  // recompterait une SECONDE fois. Changement de comportement VOULU,
  // testé (voir "DEUX invocations successives" dans evalsReconciler.test.ts).
  const timeoutMarkerResult = await writeJudgeLocalMarkerGuarded(
    stale.markerPath,
    candidate.id,
    'judging-timeout',
    'terminal-recordable',
  );
  if (!timeoutMarkerResult.ok) {
    gaps.push(
      `${candidate.id} (${candidate.kind}, skill ${candidate.skill}) : marqueur 'judging' périmé du ${stale.fileDate} — écriture 'judging-timeout' en échec après reprises (${timeoutMarkerResult.error}) — événement non finalisé, sera retraité la nuit suivante (sans double incrément)`,
    );
    outcomes.push(
      `${candidate.id} : marqueur 'judging' périmé du ${stale.fileDate} — neutralisation en échec d'écriture, échec NON enregistré cette invocation (${timeoutMarkerResult.error})`,
    );
    continue;
  }
  // Reclassé en 'environment' (revue du coordinateur, défaut J-1b) : un
  // `judging` jamais résolu signifie que le juge a été TUÉ ou INTERROMPU
  // en cours de route (machine endormie, process coupé, plantage) — la
  // `reason` ci-dessous le dit elle-même ("process interrompu pendant le
  // jugement"). Rien dans LE CANDIDAT n'a causé ça, et rien dans le
  // candidat ne le reproduira : classer ce chemin en 'candidate' (comme
  // avant cette révision) rapprochait un candidat SAIN de l'abandon sur
  // une pure panne d'infrastructure — pas théorique, mesuré dans
  // `~/Library/Logs/evals-judge-local.log` : `job-1785275228960-a6945f` a
  // vu ce chemin incrémenter son compteur deux nuits de suite (29 et
  // 30/07/2026, "marqueur 'judging' périmé... échec enregistré
  // (localJudgeAttempts = 2)"), puis a été noté 8/10 sans le moindre
  // incident dès que le process a pu tourner jusqu'au bout — la preuve
  // que le candidat n'avait jamais rien de pathologique. L'ÉVÉNEMENT
  // reste enregistré et le marqueur périmé finalisé EXACTEMENT comme
  // avant (même écriture 'judging-timeout' juste au-dessus, même
  // anti-double-comptage cross-nuit) — seul l'incrément de
  // `localJudgeAttempts` disparaît.
  const staleReason = `marqueur 'judging' du ${stale.fileDate} jamais résolu (process interrompu pendant le jugement) — traité comme échec`;
  const newAttempts = await recordJudgeLocalFailure(candidate, staleReason, 'environment');
  outcomes.push(
    `${candidate.id} : marqueur 'judging' périmé du ${stale.fileDate} — échec enregistré` +
      (newAttempts !== undefined
        ? ` (localJudgeAttempts = ${newAttempts})`
        : ' (ATTENTION : compteur localJudgeAttempts NON incrémenté)'),
  );
  if (newAttempts !== undefined) candidate.attempts = newAttempts;
  noteAbandonmentIfJustCrossed(gaps, candidate.id, candidate.kind, candidate.skill, newAttempts, cfg.localJudge.maxAttempts, staleReason);
}

// Fix P2 (revue adversariale round 3, l.2226 — "la rétention des
// marqueurs n'est branchée sur rien") : `purgeOldJudgeLocalMarkers` n'est
// sinon atteignable QUE via `evalsReconciler purge --from <bare local>`
// (voir `cmdPurge`), jamais planifié par un LaunchAgent (seuls `export`/
// `import`/`judge-local` le sont — vérifié : aucun
// `com.elmabi.evals-purge.plist` n'existe) — la purge des marqueurs
// n'avait donc JAMAIS lieu en fonctionnement réel. Branchée ici, sur le
// SEUL chemin de ce fichier qui tourne vraiment chaque nuit. Appelée
// APRÈS la réconciliation ci-dessus (jamais avant : un marqueur `judging`
// périmé de plus de 7 jours serait sinon supprimé par la purge AVANT
// d'avoir eu la chance d'incrémenter son compteur d'échec).
const markerRetention = await purgeOldJudgeLocalMarkers();

const markersToday = await readJudgeLocalMarkersForDate(date);
const {
  abandoned,
  excludedByTodayMarker,
  eligible: eligibleRaw,
  remainingQuota,
  quotaSuffix,
} = computeJudgeLocalSelection(cfg, all, markersToday);

// Effet de bord du fix "le verdict payé n'est jamais rejoué après un
// changement de jour" (`pendingReplays`/`invalidReplays` regardent
// désormais TOUTES les dates, pas seulement aujourd'hui — voir
// `readJudgeLocalMarkersForDate`) : un candidat dont le verdict d'une
// nuit PASSÉE est rejoué CETTE invocation reste `mature`+`localOnlyReason`
// (l'application avait échoué, jamais l'inverse) et peut donc AUSSI être
// un candidat FRAIS légitime pour `eligible` — son marqueur n'étant pas
// daté d'AUJOURD'HUI, le filtre `markersToday.markedIds` (scopé au jour)
// ne l'exclut pas. Sans ce filtre supplémentaire, il serait retraité une
// SECONDE fois par la boucle de sélection ci-dessous dans la MÊME
// invocation, juste après que le rejeu l'ait déjà réglé.
const replayedIds = new Set(
  [...markersToday.pendingReplays, ...markersToday.invalidReplays].map((r) => r.candidateId),
);
// Défaut J-1 (audit fiabilité rail, 2026-08-12) : la boucle ci-dessous
// n'itère plus sur une tranche PRÉ-TAILLÉE à `remainingQuota` avant tout
// traitement — un échec qui ne produit AUCUN verdict payé ('failed',
// jamais compté dans `markersToday.count`, voir sa docstring) enchaîne
// désormais sur le candidat suivant de `eligible` au lieu de sceller le
// quota de la nuit sur les deux mêmes candidats en tête de file (le
// blocage mesuré les 7-10 août). `eligible` reste trié du plus ancien
// d'abord (voir `computeJudgeLocalSelection`) — l'ordre de traitement ne
// change pas, seule la RÈGLE D'ARRÊT change (voir la boucle plus bas).
const eligible = eligibleRaw.filter((c) => !replayedIds.has(c.id));

let successCount = 0;
let failureCount = 0;
/** Nombre de verdicts RÉELLEMENT PAYÉS (`judged.ok === true`) cette
 *  invocation — distinct de `successCount` (incrémenté seulement si
 *  l'APPLICATION du verdict réussit aussi) : un verdict payé dont
 *  l'application échoue consomme QUAND MÊME une place de
 *  `remainingQuota` (défaut J-1) — sans ce compteur dédié, une série
 *  d'échecs d'application (jamais de jugement) laisserait la boucle
 *  continuer de payer des jugements bien au-delà du quota réel de la
 *  nuit, `successCount` restant artificiellement bas. */
let paidThisInvocation = 0;
/**
 * Coupe-circuit (défaut J-1, point b) : nombre d'échecs de JUGEMENT
 * CONSÉCUTIFS pendant CETTE invocation — remis à zéro par tout succès.
 * Porte UNIQUEMENT sur les deux branches d'échec de la boucle de
 * sélection plus bas (l'exception non-fail-closed autour de
 * `runLocalJudge`, et `judged.ok === false`) — jamais sur un échec
 * d'APPLICATION post-verdict (rejeu ou frais : le jugement, lui, a
 * réussi, ce n'est pas un signal de panne du JUGE) ni sur les rejeux
 * `pendingReplays`/`invalidReplays` (candidats d'une nuit précédente,
 * hors périmètre de "cette invocation échoue en boucle MAINTENANT").
 * Dès que ce compteur atteint `localJudge.maxConsecutiveFailures`
 * (défaut 2), la nuit s'arrête : c'est LE cas systémique (une panne
 * d'API ferait sinon défiler tout le backlog en une seule invocation),
 * et lui SEUL ouvre la conversation d'écart en `'approval'` — voir la
 * fin de cette fonction.
 */
let consecutiveFailures = 0;
let circuitBreakerTripped = false;
/** Défaut J-1, point c — borne dure indépendante, voir sa docstring.
 *  Fix A6 (audit fiabilité rail) : porte désormais la RAISON précise
 *  (attempts vs durée, voir la boucle plus bas) — routée dans `gaps`
 *  ET dans les lignes finales, jamais seulement l'une des deux (l'ancien
 *  comportement, malgré la docstring de `JUDGE_LOCAL_MAX_ATTEMPTS_PER_INVOCATION`
 *  qui promettait les deux). */
let hardCapReached = false;
let hardCapReason: string | undefined;
/** Candidats RÉELLEMENT tentés (succès + échecs) cette invocation — sert
 *  au rapport ("Traités : N") et au calcul du `leftover` dynamique
 *  (remplace `selected`/`leftover` pré-tranchés d'avant ce lot). */
const attempted: JudgeLocalCandidate[] = [];
/** IDs des candidats en échec de JUGEMENT pendant cette invocation — sert
 *  de signature au dédup des conversations d'écart (défaut J-3, voir
 *  `openOrAppendJudgeLocalGap`). */
const failedCandidateIds: string[] = [];

// Fix P3 (revue adversariale round 3 — "timeoutMinutes n'est pas borné
// par LOCK_STALE_MS") : signalé UNE FOIS par invocation (pas par
// candidat, la config ne change pas entre deux candidats) plutôt qu'à
// chaque appel de `runLocalJudge` — c'est une MISCONFIGURATION à
// corriger dans `config/evals.json`, pas un échec de candidat, donc dans
// `gaps` directement (jamais `noteAbandonmentIfJustCrossed`, qui parle de
// candidats, pas de config).
if (cfg.localJudge.timeoutMinutes > MAX_SAFE_JUDGE_TIMEOUT_MINUTES) {
  gaps.push(
    `Configuration : localJudge.timeoutMinutes=${cfg.localJudge.timeoutMinutes} dépasse la marge sûre ` +
      `(${MAX_SAFE_JUDGE_TIMEOUT_MINUTES} min) avant péremption du verrou partagé (LOCK_STALE_MS=30 min) — ` +
      `ce run plafonne le timeout EFFECTIF à ${MAX_SAFE_JUDGE_TIMEOUT_MINUTES} min pour chaque candidat ` +
      '(voir safeJudgeTimeoutMinutes) ; réduire localJudge.timeoutMinutes dans config/evals.json pour que la config reflète ce qui est réellement appliqué.',
  );
}

// Sessions dont le transcript reste introuvable (ni CapturedSession, ni
// quarantaine). Fix P2 (revue adversariale round 2, l.2420 — "les
// sessions irrésolubles contournent marqueur ET maxAttempts") : bornées
// désormais par les MÊMES garde-fous que tout autre candidat —
// `maxAttempts` (au-delà, déjà signalé la nuit où le seuil a été franchi,
// jamais ré-enregistré ici) ET un marqueur du jour (`unresolvable-
// transcript`, exclu de `count` — voir sa docstring — pour ne pas
// grignoter le quota RÉEL de `maxPerNight`, qui ne borne que les vrais
// jugements payés) pour qu'une seconde invocation la même nuit ne
// consomme pas une deuxième tentative pour la même session. Avant ce
// fix, chaque invocation (RunAtLoad + « Run now » + 4h00, potentiellement
// plusieurs fois la même nuit) brûlait une tentative supplémentaire, pour
// toujours, sans jamais s'arrêter.
for (const stamp of unresolvableSessions) {
  if (markersToday.markedIds.has(stamp.sessionId)) {
    outcomes.push(`${stamp.sessionId} : transcript introuvable, déjà enregistré aujourd'hui (marqueur présent) — sauté`);
    continue;
  }
  if ((stamp.localJudgeAttempts ?? 0) >= cfg.localJudge.maxAttempts) {
    // Déjà abandonné AVANT cette invocation — signalé la nuit où il a
    // franchi le seuil (voir `noteAbandonmentIfJustCrossed`), jamais
    // ré-enregistré ni re-signalé ici. Reste visible dans
    // `judgeLocalUnresolvableLine` (liste brute, non filtrée).
    continue;
  }
  const pseudoCandidate: JudgeLocalCandidate = {
    kind: 'session',
    id: stamp.sessionId,
    skill: SESSION_JUDGE_SKILL,
    transcriptPath: '',
    attempts: stamp.localJudgeAttempts ?? 0,
    anchorMs: 0,
    stamp,
  };
  // Marqueur AVANT l'effet de bord (même contrat que partout ailleurs
  // dans ce fichier) : un crash entre les deux laisse ce candidat non
  // recompté aujourd'hui plutôt que risquer un double incrément la même
  // nuit.
  // Sous-contrat 3bis (D2) : marqueur D'ABORD (reprise bornée), PUIS
  // `recordJudgeLocalFailure` UNIQUEMENT si le marqueur a été finalisé —
  // l'ordre ici était DÉJÀ correct avant ce fix (aucune inversion), mais
  // l'écriture elle-même restait NUE (une exception ici aurait abandonné
  // toute la boucle des sessions irrésolubles restantes).
  const unresolvableMarkerResult = await writeJudgeLocalMarkerGuarded(
    judgeLocalMarkerPath(date, stamp.sessionId),
    stamp.sessionId,
    'unresolvable-transcript',
