/** Fetches `ref` from `remote` (a local bare path OR a URL) into a scratch
 *  git dir and exposes its tree via `git show <sha>:<path>`. Returns
 *  `undefined` if the branch does not exist / the remote is unreachable —
 *  never throws (a missing branch is an expected "gap", not a crash). */
async function fetchBranchContent(remote: string, ref: string, scratchDir: string): Promise<FetchedBranch | undefined> {
  const remoteRef = `refs/remotes/evals-fetch/${ref.replace(/\//g, '-')}`;
  try {
    execFileSync('git', ['fetch', '-q', remote, `${ref}:${remoteRef}`], {
      cwd: scratchDir,
      stdio: ['ignore', 'ignore', 'pipe'],
    });
  } catch {
    return undefined;
  }
  let sha: string;
  try {
    sha = execFileSync('git', ['rev-parse', remoteRef], { cwd: scratchDir, encoding: 'utf8' }).trim();
  } catch {
    return undefined;
  }
  const readTextFile = (relPath: string): string | undefined => {
    try {
      return execFileSync('git', ['show', `${sha}:${relPath}`], { cwd: scratchDir, encoding: 'utf8' });
    } catch {
      return undefined;
    }
  };
  const listFiles = (): string[] => {
    try {
      return execFileSync('git', ['ls-tree', '-r', '--name-only', sha], { cwd: scratchDir, encoding: 'utf8' })
        .split('\n')
        .map((l) => l.trim())
        .filter(Boolean);
    } catch {
      return [];
    }
  };
  return { sha, readTextFile, listFiles };
}

