3937	  // OPTIONNELLE, embarquée dans le récit — voir `judgeLocalGapSignatureTag`
3938	  // et `findOpenJudgeLocalGapConversation`. AUCUN appelant `import-cloud` ne
3939	  // la passe : comportement byte-identique préservé pour cette source.
3940	  dedupSignature?: string,
3941	): Promise<{ ok: boolean; detail: string }> {
3942	  const copy = GAP_SOURCE_COPY[source];
3943	  const id = invocationDiscriminant
3944	    ? `${todayUtcDate()}-ecart-${copy.idSlug}-${date}-${invocationDiscriminant}`
3945	    : `${todayUtcDate()}-ecart-${copy.idSlug}-${date}`;
3946	  const gapsText = gaps.map((g) => `- ${g}`).join('\n') + (dedupSignature ? judgeLocalGapSignatureTag(dedupSignature) : '');
3947	  const item =
3948	    severity === 'approval'
3949	      ? {
3950	          id: 'ecart-decision',
3951	          kind: 'approval' as const,
3952	          prompt: copy.approvalPrompt(date),
3953	          context: gapsText,
3954	        }
3955	      : {
3956	          id: 'ecart-note',
3957	          kind: 'note' as const,
3958	          prompt: copy.noteHeadline(date),
3959	          context: copy.noteContext,
3960	          body: gapsText,
3961	        };
3962	  const payload = {
3963	    id,
3964	    project: { slug: 'workstation', name: 'workstation' },
3965	    title: copy.title(date),
3966	    summary: copy.summary(date),
3967	    items: [item],
3968	  };
3969	
3970	  // `convo.ts` lives NEXT TO this file on disk — resolved via `import.meta.dir`,
3971	  // NEVER via `root()`: `root()` follows `WORKSTATION_ROOT` (a test's isolated
3972	  // DATA root override), which is not where the actual CLI source lives.
3973	  // `WORKSTATION_ROOT` still flows to the child through `env: process.env`
3974	  // (inherited from however THIS process was itself spawned), so the
3975	  // conversation is written under the SAME isolated root as everything else.
3976	  const proc = Bun.spawn(['bun', path.join(import.meta.dir, 'convo.ts'), 'create', 'workstation', '-'], {
3977	    env: process.env,
3978	    stdin: 'pipe',
3979	    stdout: 'pipe',
3980	    stderr: 'pipe',
3981	  });
3982	  proc.stdin.write(JSON.stringify(payload));
3983	  await proc.stdin.end();
3984	  const code = await proc.exited;
3985	  if (code === 0) {
3986	    return { ok: true, detail: `conversation workstation/${id} ouverte` };
3987	  }
3988	  const err = await new Response(proc.stderr).text();
