async function openGapConversation(
  date: string,
  gaps: string[],
  severity: 'approval' | 'note',
  source: GapSource = 'import-cloud',
  invocationDiscriminant?: string,
  // Défaut J-3 (audit fiabilité rail, 2026-08-12) : signature de dédup
  // OPTIONNELLE, embarquée dans le récit — voir `judgeLocalGapSignatureTag`
  // et `findOpenJudgeLocalGapConversation`. AUCUN appelant `import-cloud` ne
  // la passe : comportement byte-identique préservé pour cette source.
  dedupSignature?: string,
): Promise<{ ok: boolean; detail: string }> {
  const copy = GAP_SOURCE_COPY[source];
  const id = invocationDiscriminant
    ? `${todayUtcDate()}-ecart-${copy.idSlug}-${date}-${invocationDiscriminant}`
    : `${todayUtcDate()}-ecart-${copy.idSlug}-${date}`;
  const gapsText = gaps.map((g) => `- ${g}`).join('\n') + (dedupSignature ? judgeLocalGapSignatureTag(dedupSignature) : '');
  const item =
    severity === 'approval'
      ? {
          id: 'ecart-decision',
          kind: 'approval' as const,
          prompt: copy.approvalPrompt(date),
          context: gapsText,
        }
      : {
          id: 'ecart-note',
          kind: 'note' as const,
          prompt: copy.noteHeadline(date),
          context: copy.noteContext,
          body: gapsText,
        };
  const payload = {
    id,
    project: { slug: 'workstation', name: 'workstation' },
    title: copy.title(date),
    summary: copy.summary(date),
    items: [item],
  };

  // `convo.ts` lives NEXT TO this file on disk — resolved via `import.meta.dir`,
  // NEVER via `root()`: `root()` follows `WORKSTATION_ROOT` (a test's isolated
  // DATA root override), which is not where the actual CLI source lives.
  // `WORKSTATION_ROOT` still flows to the child through `env: process.env`
  // (inherited from however THIS process was itself spawned), so the
  // conversation is written under the SAME isolated root as everything else.
  const proc = Bun.spawn(['bun', path.join(import.meta.dir, 'convo.ts'), 'create', 'workstation', '-'], {
    env: process.env,
    stdin: 'pipe',
    stdout: 'pipe',
    stderr: 'pipe',
  });
  proc.stdin.write(JSON.stringify(payload));
  await proc.stdin.end();
  const code = await proc.exited;
  if (code === 0) {
    return { ok: true, detail: `conversation workstation/${id} ouverte` };
  }
  const err = await new Response(proc.stderr).text();
  // Idempotence : le reconciler peut repasser plusieurs fois le même jour
  // (RunAtLoad + « Run now » + 4h00). L'id de conversation étant déterministe
  // par date, un « already exists » signifie que l'écart est DÉJÀ signalé au
  // hub (et contient peut-être une réponse humaine) — c'est un succès, pas un
  // échec, et surtout pas une invitation à --force (qui écraserait la réponse).
  if (err.includes('already exists')) {
    return { ok: true, detail: `écart déjà signalé — conversation workstation/${id} existante (non rouverte)` };
  }
  return { ok: false, detail: `échec de création de la conversation d'écart : ${err.trim() || `exit ${code}`}` };
}

