test("transcript au-delà du cap du juge local -> à l'abandon, l'écart cite la DERNIÈRE CAUSE (vécu 2026-10-01 : 149 Mo > 50 Mo, abandon sans raison dite)", async () => {
  await importStore();
  const root = await freshRoot({ localJudge: { enabled: true, maxAttempts: 1, maxPerNight: 2 } });

  // Fichier creux de 50 000 001 o : `stat()` dépasse le cap FIXE du juge local (50 000 000 o, volontairement
  // hors config) et le refus tombe AVANT toute lecture — aucun octet écrit sur disque, aucun `claude -p` lancé.
  const bigT = await writeTranscript(root, 'oversize.jsonl', 'x\n');
  await truncate(bigT, 50_000_001);
  const job = await store.createSkillJob(baseSkillJobInput({ transcriptPath: bigT, state: 'mature' }));
  await store.updateSkillJob(job.id, { localOnlyReason: 'r' }, job.updatedAt);

  const cmd = await fakeJudgeCmd("console.log('{}');");
  const { stdout } = await run(root, ['judge-local'], { EVALS_LOCAL_JUDGE_FAKE_CMD: cmd });
  expect(stdout).toContain(`${job.id} : ÉCHEC`);

  const conv = await findJudgeLocalGapConversation(todayUtcDate());
  expect(conv).not.toBeNull();
  const convText = JSON.stringify(conv);
  expect(convText).toContain('abandonné après 1 échec(s) local');
  expect(convText).toContain('dernière cause : transcript 50000001o > cap 50000000o — refusé avant lecture complète');
});

test('le verrou est rafraîchi (touch) entre deux candidats — ne doit pas expirer pendant un run multi-candidats (fix verrou)', async () => {
  await importStore();
  const root = await freshRoot({ localJudge: { enabled: true, maxPerNight: 2 } });

  const t1 = await writeTranscript(root, 'lockjob1.jsonl', 'contenu 1\n');
  let job1 = await store.createSkillJob(
    baseSkillJobInput({ transcriptPath: t1, state: 'mature', capturedAt: '2026-01-01T00:00:00.000Z' }),
  );
  job1 = await store.updateSkillJob(job1.id, { localOnlyReason: 'r1' }, job1.updatedAt);

